      "A regra de ouro da concordância verbal é: o verbo concorda em número e pessoa com o núcleo do sujeito. O primeiro passo em qualquer questão é sempre localizar o sujeito e, dentro dele, identificar o núcleo — a palavra que realmente determina a concordância, ignorando os termos que a acompanham (adjuntos, apostos).",
      "Com sujeito composto (dois ou mais núcleos) antes do verbo, a concordância vai para o plural: 'O delegado e o escrivão assinaram o auto'. Quando o sujeito composto vem depois do verbo, a concordância pode ir para o plural (mais formal) ou concordar só com o núcleo mais próximo (mais comum na fala, mas aceito também em registro formal): 'Compareceram (ou compareceu) o delegado e o escrivão'.",
