      "A vírgula marca pausas breves e separa elementos dentro da frase, mas segue regras precisas — não é uma questão de 'onde soa melhor pausar ao ler'. As situações mais cobradas em prova são: separar elementos de uma enumeração, isolar aposto e vocativo, marcar a inversão da ordem direta da oração, e isolar orações intercaladas.",
      "A regra mais importante — e mais violada — é: nunca se separa sujeito de predicado com vírgula, nem verbo de complemento, quando estão na ordem direta: 'O delegado, assinou o documento' está errado; o correto é 'O delegado assinou o documento', sem vírgula.",
      "Quando um termo é deslocado de sua posição normal na frase (geralmente um adjunto adverbial no início), a vírgula se torna necessária ou recomendada: 'Depois da operação, os policiais retornaram à base' (o adjunto 'depois da operação' foi deslocado para o início, por isso a vírgula)."
