    "corpo": [
      "Ponto e vírgula separa orações que têm certa independência entre si, mas que estão relacionadas em sentido — funciona como uma pausa mais forte que a vírgula, mas mais fraca que o ponto final. É muito usado para separar itens de uma enumeração complexa (quando os itens já têm vírgula interna) e para separar orações coordenadas de sentido oposto, quando se quer dar mais destaque à separação do que uma simples vírgula daria.",
      "Dois-pontos introduzem uma explicação, uma enumeração, uma citação direta, ou a fala de alguém: 'A operação teve três fases: planejamento, execução e avaliação'. Nunca se usa dois-pontos entre verbo e complemento direto na ordem direta, mesmo que o complemento seja uma enumeração longa.",
      "Travessão tem duas funções principais: marcar a fala de um interlocutor em diálogo, e isolar uma explicação ou comentário intercalado no meio da frase, funcionando de forma parecida com o parêntese, mas com mais destaque visual: 'O suspeito — que já tinha passagem pela polícia — foi detido novamente'."
    ],
    "pontosChave": [
      "Ponto e vírgula separa itens de enumeração complexa (já com vírgula interna) ou orações coordenadas de sentido contrastante.",
      "Dois-pontos introduzem explicação, enumeração ou citação — nunca entre verbo e complemento direto.",
      "Travessão isola comentário intercalado (como um parêntese com mais destaque) ou marca fala em diálogo."
    ],
