      "Questões de reescrita pedem para o candidato avaliar se uma nova versão de uma frase preserva o sentido original, mantendo a correção gramatical. É um tipo de questão que combina tudo que foi visto nos capítulos anteriores: concordância, regência, crase, pontuação e coesão.",
      "O erro mais comum é aceitar uma reescrita que muda sutilmente o sentido original — trocar uma causa por uma condição, por exemplo, ou trocar um fato certo (indicativo) por uma hipótese (subjuntivo). A banca também testa transformações de voz ativa para passiva, de discurso direto para indireto, e substituições por sinônimos que nem sempre mantêm o mesmo peso semântico.",
      "A estratégia mais segura é: primeiro, entenda exatamente o que a frase original quer dizer, sem se prender às palavras específicas. Depois, compare com a reescrita perguntando: essa nova frase permite a mesma interpretação, sem acrescentar nem tirar informação? Só depois disso, verifique se a reescrita está gramaticalmente correta."
